// Price Alert Monitor v6 - TTS-friendly titles, no fallback config
// Edit config/price-alerts.yaml to change thresholds!

// Helper: Convert price to TTS-friendly speech
// Drops .00 cents to avoid "four hundred point zero zero" sounding like "400,000"
function priceToSpeech(price) {
  // Check if price is a whole number (no meaningful cents)
  const isWhole = price % 1 === 0 || Math.abs(price % 1) < 0.01;

  if (price >= 1000000) {
    const millions = price / 1000000;
    return isWhole ? `${Math.round(millions)} million dollars` : `${millions.toFixed(1)} million dollars`;
  } else if (price >= 1000) {
    return `${Math.round(price).toLocaleString()} dollars`;
  } else {
    // For small prices: $400 not $400.00, but $142.50 keeps cents
    return isWhole ? `${Math.round(price)} dollars` : `${price.toFixed(2)} dollars`;
  }
}

// Get all input items from Merge node
const allItems = $input.all();

// Find config and price data
let config = null;
let cryptoData = null;
let tslaData = null;
let goldData = null;

for (const item of allItems) {
  const json = item.json;

  // Config response from /api/config/price-alerts
  if (json.watchlist) {
    config = json;
  }
  // CoinGecko response has bitcoin/solana keys
  else if (json.bitcoin || json.solana) {
    cryptoData = json;
  }
  // Direct API responses have 'ok' and 'data' with 'symbol'
  else if (json.ok && json.data && json.data.symbol) {
    const symbol = json.data.symbol;
    if (symbol === 'TSLA') {
      tslaData = json.data;
    } else if (symbol === 'GC=F') {
      goldData = json.data;
    }
  }
}

const alerts = [];
const now = new Date().toISOString();

// If config fetch failed, send error alert and stop
if (!config || !config.watchlist) {
  return [{ json: { 
    title: 'Price monitor config error - check Jarvis API',
    description: 'Could not fetch price-alerts.yaml config. Check if Jarvis API is running.',
    severity: 'medium',
    source: 'price_monitor',
    metadata: { error: 'config_fetch_failed', checked_at: now }
  }}];
}

// Helper to find threshold from config
function getThreshold(watchlist, assetType, symbol, conditionType) {
  const assets = watchlist[assetType] || [];
  const asset = assets.find(a => a.symbol === symbol && a.enabled !== false);
  if (!asset) return null;
  const cond = (asset.conditions || []).find(c => c.type === conditionType);
  return cond ? { value: cond.value, name: asset.name } : null;
}

// Check BTC
if (cryptoData && cryptoData.bitcoin) {
  const btc = cryptoData.bitcoin;
  const price = btc.usd;
  const change24h = btc.usd_24h_change || 0;
  const name = 'Bitcoin';

  const aboveThresh = getThreshold(config.watchlist, 'crypto', 'BTC', 'above');
  const belowThresh = getThreshold(config.watchlist, 'crypto', 'BTC', 'below');
  const changeThresh = getThreshold(config.watchlist, 'crypto', 'BTC', 'percent_change_24h');

  if (aboveThresh && price >= aboveThresh.value) {
    alerts.push({
      title: `${name} is at ${priceToSpeech(price)}, above your ${priceToSpeech(aboveThresh.value)} target`,
      description: `${name} hit ${priceToSpeech(aboveThresh.value)}! Currently at ${priceToSpeech(price)}.`,
      severity: 'high',
      source: 'price_monitor',
      metadata: { symbol: 'BTC', price, threshold: aboveThresh.value, type: 'above' }
    });
  }
  if (belowThresh && price <= belowThresh.value) {
    alerts.push({
      title: `${name} dropped to ${priceToSpeech(price)}, below your ${priceToSpeech(belowThresh.value)} target`,
      description: `${name} dropped below ${priceToSpeech(belowThresh.value)}. Currently at ${priceToSpeech(price)}.`,
      severity: 'high',
      source: 'price_monitor',
      metadata: { symbol: 'BTC', price, threshold: belowThresh.value, type: 'below' }
    });
  }
  if (changeThresh && Math.abs(change24h) >= changeThresh.value) {
    const direction = change24h > 0 ? 'up' : 'down';
    alerts.push({
      title: `${name} moved ${Math.abs(change24h).toFixed(1)} percent ${direction} today, now at ${priceToSpeech(price)}`,
      description: `${name} moved ${Math.abs(change24h).toFixed(1)} percent in 24 hours.`,
      severity: 'high',
      source: 'price_monitor',
      metadata: { symbol: 'BTC', price, change_24h: change24h, type: 'percent_change' }
    });
  }
}

// Check SOL
if (cryptoData && cryptoData.solana) {
  const sol = cryptoData.solana;
  const price = sol.usd;
  const change24h = sol.usd_24h_change || 0;
  const name = 'Solana';

  const aboveThresh = getThreshold(config.watchlist, 'crypto', 'SOL', 'above');
  const belowThresh = getThreshold(config.watchlist, 'crypto', 'SOL', 'below');
  const changeThresh = getThreshold(config.watchlist, 'crypto', 'SOL', 'percent_change_24h');

  if (aboveThresh && price >= aboveThresh.value) {
    alerts.push({
      title: `${name} is at ${priceToSpeech(price)}, above your ${priceToSpeech(aboveThresh.value)} target`,
      description: `${name} above ${priceToSpeech(aboveThresh.value)}! Currently at ${priceToSpeech(price)}.`,
      severity: 'high',
      source: 'price_monitor',
      metadata: { symbol: 'SOL', price, threshold: aboveThresh.value, type: 'above' }
    });
  }
  if (belowThresh && price <= belowThresh.value) {
    alerts.push({
      title: `${name} dropped to ${priceToSpeech(price)}, below your ${priceToSpeech(belowThresh.value)} target`,
      description: `${name} dropped below ${priceToSpeech(belowThresh.value)}. Currently at ${priceToSpeech(price)}.`,
      severity: 'high',
      source: 'price_monitor',
      metadata: { symbol: 'SOL', price, threshold: belowThresh.value, type: 'below' }
    });
  }
  if (changeThresh && Math.abs(change24h) >= changeThresh.value) {
    const direction = change24h > 0 ? 'up' : 'down';
    alerts.push({
      title: `${name} moved ${Math.abs(change24h).toFixed(1)} percent ${direction} today, now at ${priceToSpeech(price)}`,
      description: `${name} moved ${Math.abs(change24h).toFixed(1)} percent in 24 hours.`,
      severity: 'high',
      source: 'price_monitor',
      metadata: { symbol: 'SOL', price, change_24h: change24h, type: 'percent_change' }
    });
  }
}

// Check TSLA
if (tslaData) {
  const price = tslaData.price_usd;
  const change = tslaData.change_today_percent || 0;
  const name = 'Tesla';

  const aboveThresh = getThreshold(config.watchlist, 'stocks', 'TSLA', 'above');
  const belowThresh = getThreshold(config.watchlist, 'stocks', 'TSLA', 'below');
  const changeThresh = getThreshold(config.watchlist, 'stocks', 'TSLA', 'percent_change_24h');

  if (price && aboveThresh && price >= aboveThresh.value) {
    alerts.push({
      title: `${name} is at ${priceToSpeech(price)}, above your ${priceToSpeech(aboveThresh.value)} target`,
      description: `${name} above ${priceToSpeech(aboveThresh.value)}! Currently at ${priceToSpeech(price)}.`,
      severity: 'high',
      source: 'price_monitor',
      metadata: { symbol: 'TSLA', price, threshold: aboveThresh.value, type: 'above' }
    });
  }
  if (price && belowThresh && price <= belowThresh.value) {
    alerts.push({
      title: `${name} dropped to ${priceToSpeech(price)}, below your ${priceToSpeech(belowThresh.value)} target`,
      description: `${name} dropped below ${priceToSpeech(belowThresh.value)}. Currently at ${priceToSpeech(price)}.`,
      severity: 'high',
      source: 'price_monitor',
      metadata: { symbol: 'TSLA', price, threshold: belowThresh.value, type: 'below' }
    });
  }
  if (price && changeThresh && Math.abs(change) >= changeThresh.value) {
    const direction = change > 0 ? 'up' : 'down';
    alerts.push({
      title: `${name} moved ${Math.abs(change).toFixed(1)} percent ${direction} today, now at ${priceToSpeech(price)}`,
      description: `${name} moved ${Math.abs(change).toFixed(1)} percent today.`,
      severity: 'high',
      source: 'price_monitor',
      metadata: { symbol: 'TSLA', price, change_percent: change, type: 'percent_change' }
    });
  }
}

// Check Gold
if (goldData) {
  const price = goldData.price_usd;
  const change = goldData.change_today_percent || 0;
  const name = 'Gold';

  const aboveThresh = getThreshold(config.watchlist, 'stocks', 'GC=F', 'above');
  const belowThresh = getThreshold(config.watchlist, 'stocks', 'GC=F', 'below');
  const changeThresh = getThreshold(config.watchlist, 'stocks', 'GC=F', 'percent_change_24h');

  if (price && aboveThresh && price >= aboveThresh.value) {
    alerts.push({
      title: `${name} is at ${priceToSpeech(price)} per ounce, above your ${priceToSpeech(aboveThresh.value)} target`,
      description: `${name} above ${priceToSpeech(aboveThresh.value)} per ounce! Currently at ${priceToSpeech(price)}.`,
      severity: 'high',
      source: 'price_monitor',
      metadata: { symbol: 'GC=F', price, threshold: aboveThresh.value, type: 'above' }
    });
  }
  if (price && belowThresh && price <= belowThresh.value) {
    alerts.push({
      title: `${name} dropped to ${priceToSpeech(price)}, below your ${priceToSpeech(belowThresh.value)} target`,
      description: `${name} dropped below ${priceToSpeech(belowThresh.value)}. Currently at ${priceToSpeech(price)}.`,
      severity: 'high',
      source: 'price_monitor',
      metadata: { symbol: 'GC=F', price, threshold: belowThresh.value, type: 'below' }
    });
  }
  if (price && changeThresh && Math.abs(change) >= changeThresh.value) {
    const direction = change > 0 ? 'up' : 'down';
    alerts.push({
      title: `${name} moved ${Math.abs(change).toFixed(1)} percent ${direction} today, now at ${priceToSpeech(price)}`,
      description: `${name} moved ${Math.abs(change).toFixed(1)} percent today.`,
      severity: 'high',
      source: 'price_monitor',
      metadata: { symbol: 'GC=F', price, change_percent: change, type: 'percent_change' }
    });
  }
}

// Return alerts (or empty if none triggered)
return alerts.length > 0 ? alerts.map(a => ({ json: a })) : [{ json: { no_alerts: true, checked_at: now } }];
